  "src/core/diagnostics/Profiler.ts": "export class Profiler {\n  private fps: number = 0;\n  private frameCount: number = 0;\n  private lastTime: number = performance.now();\n\n  public update(): void {\n    this.frameCount++;\n    const now = performance.now();\n    if (now - this.lastTime >= 1000) {\n      this.fps = this.frameCount;\n      this.frameCount = 0;\n      this.lastTime = now;\n    }\n  }\n\n  public getFps(): number {\n    return this.fps;\n  }\n}\n",
  "src/core/engine/Engine.ts": "import { GameLoop } from \"../loop/GameLoop\";\nimport { EventBroker } from \"../events/EventBroker\";\nimport { SystemManager } from \"../systems/SystemManager\";\n\nexport class Engine {\n    private loop: GameLoop;\n    private broker: EventBroker;\n    private systemManager: SystemManager;\n    private canvas: HTMLCanvasElement;\n\n    constructor(canvas: HTMLCanvasElement, broker: EventBroker, systemManager: SystemManager) {\n        this.canvas = canvas;\n        this.broker = broker;\n        this.systemManager = systemManager;\n        \n        this.loop = new GameLoop(\n            (dt) => this.update(dt),\n            (alpha) => this.render(alpha)\n        );\n    }\n\n    public start(): void {\n        this.systemManager.initAll();\n        this.loop.start();\n    }\n\n    public stop(): void {\n        this.loop.stop();\n        this.systemManager.disposeAll();\n    }\n\n    private update(dt: number): void {\n        this.systemManager.updateAll(dt);\n    }\n\n    private render(alpha: number): void {\n        this.systemManager.renderAll(alpha);\n    }\n}\n",
  "src/core/events/EventBroker.ts": "import { GameEvent, GameEventMap } from \"./GameEvents\";\n\nexport type EventCallback<T> = (payload: T) => void;\n\nexport class EventBroker {\n  private listeners: { [K in GameEvent]?: Set<EventCallback<any>> } = {};\n\n  public subscribe<K extends GameEvent>(event: K, cb: EventCallback<GameEventMap[K]>): () => void {\n    if (!this.listeners[event]) {\n      this.listeners[event] = new Set();\n    }\n    this.listeners[event]!.add(cb);\n    return () => {\n      this.listeners[event]?.delete(cb);\n    };\n  }\n\n  public publish<K extends GameEvent>(event: K, payload: GameEventMap[K]): void {\n    const set = this.listeners[event];\n    if (set) {\n      set.forEach((cb) => cb(payload));\n    }\n  }\n\n  public clear(): void {\n    this.listeners = {};\n  }\n}\n",
  "src/core/events/GameEvents.ts": "export enum GameEvent {\n  GAME_INITIALIZED = \"GAME_INITIALIZED\",\n  USER_GESTURE_REGISTERED = \"USER_GESTURE_REGISTERED\",\n  PLAYER_MOVE = \"PLAYER_MOVE\",\n  PLAYER_HEALTH_CHANGED = \"PLAYER_HEALTH_CHANGED\",\n  PLAYER_VELOCITY_CHANGED = \"PLAYER_VELOCITY_CHANGED\",\n  ROPE_TENSION_CHANGE = \"ROPE_TENSION_CHANGE\",\n  ROPE_LENGTH_CHANGE = \"ROPE_LENGTH_CHANGE\",\n  WARDEN_STATE_CHANGE = \"WARDEN_STATE_CHANGE\",\n  CAMERA_SHAKE_TRIGGERED = \"CAMERA_SHAKE_TRIGGERED\"\n}\n\nexport interface GameEventMap {\n  [GameEvent.GAME_INITIALIZED]: void;\n  [GameEvent.USER_GESTURE_REGISTERED]: void;\n  [GameEvent.PLAYER_MOVE]: { x: number; y: number; z: number };\n  [GameEvent.PLAYER_HEALTH_CHANGED]: { hp: number; maxHp: number };\n  [GameEvent.PLAYER_VELOCITY_CHANGED]: { velocity: number; maxVelocity: number };\n  [GameEvent.ROPE_TENSION_CHANGE]: { tension: number };\n  [GameEvent.ROPE_LENGTH_CHANGE]: { length: number; maxLength: number };\n  [GameEvent.WARDEN_STATE_CHANGE]: { state: string; hue: string };\n  [GameEvent.CAMERA_SHAKE_TRIGGERED]: { amplitude: number; duration: number };\n}\n",
  "src/core/loop/GameLoop.ts": "export class GameLoop {\n  private isRunning: boolean = false;\n  private lastTime: number = 0;\n  private accumulator: number = 0;\n  private readonly fixedStep: number = 1 / 60;\n  private onUpdate: (dt: number) => void;\n  private onRender: (interpolationAlpha: number) => void;\n  private rafId: number | null = null;\n\n  constructor(onUpdate: (dt: number) => void, onRender: (interpolationAlpha: number) => void) {\n    this.onUpdate = onUpdate;\n    this.onRender = onRender;\n    if (typeof window !== \"undefined\") {\n      document.addEventListener(\"visibilitychange\", this.handleVisibilityChange);\n    }\n  }\n\n  public start(): void {\n    if (this.isRunning) return;\n    this.isRunning = true;\n    this.lastTime = performance.now();\n    this.accumulator = 0;\n    this.rafId = requestAnimationFrame((t) => this.tick(t));\n  }\n\n  public stop(): void {\n    this.isRunning = false;\n    if (this.rafId !== null) {\n      cancelAnimationFrame(this.rafId);\n      this.rafId = null;\n    }\n  }\n\n  private tick(now: number): void {\n    if (!this.isRunning) return;\n    let dt = (now - this.lastTime) / 1000;\n    this.lastTime = now;\n\n    if (dt > 0.1) {\n      dt = 0.1;\n    }\n    this.accumulator += dt;\n\n    while (this.accumulator >= this.fixedStep) {\n      this.onUpdate(this.fixedStep);\n      this.accumulator -= this.fixedStep;\n    }\n\n    const alpha = this.accumulator / this.fixedStep;\n    this.onRender(alpha);\n\n    this.rafId = requestAnimationFrame((t) => this.tick(t));\n  }\n\n  private handleVisibilityChange = (): void => {\n    if (document.hidden) {\n      this.stop;\n    } else {\n      this.start();\n    }\n  };\n\n  public cleanup(): void {\n    this.stop();\n    if (typeof window !== \"undefined\") {\n      document.removeEventListener(\"visibilitychange\", this.handleVisibilityChange);\n    }\n  }\n}\n",
  "src/core/systems/SystemManager.ts": "import { ISystem } from \"../../contracts/ISystem\";\n\nexport class SystemManager {\n    private systems: ISystem[] = [];\n\n    public register(system: ISystem): void {\n        this.systems.push(system);\n    }\n\n    public initAll(): void {\n        for (const system of this.systems) {\n            if (system.init) system.init();\n        }\n    }\n\n    public updateAll(dt: number): void {\n        for (const system of this.systems) {\n            system.update(dt);\n        }\n    }\n\n    public renderAll(alpha: number): void {\n        for (const system of this.systems) {\n            if (system.render) system.render(alpha);\n        }\n    }\n\n    public disposeAll(): void {\n        for (const system of this.systems) {\n            if (system.dispose) system.dispose();\n        }\n    }\n}\n",
