  "src/gameplay/states/IWardenState.ts": "import { WardenData } from \"../components/WardenData\";\n\nexport type WardenStateType = \"DORMANT\" | \"HUNTING\";\n\nexport interface IWardenState {\n    readonly type: WardenStateType;\n    readonly name: string;\n    readonly hue: string;\n    enter(data: WardenData): void;\n    exit(data: WardenData): void;\n    update(data: WardenData, dt: number): WardenStateType | null;\n}\n",
  "src/gameplay/states/WardenDormantState.ts": "import { WardenData } from \"../components/WardenData\";\nimport { IWardenState, WardenStateType } from \"./IWardenState\";\n\nexport class WardenDormantState implements IWardenState {\n    public readonly type: WardenStateType = \"DORMANT\";\n    public readonly name = \"DORMANT\";\n    public readonly hue = \"#6b7280\";\n\n    public enter(data: WardenData): void {\n        data.timeInState = 0;\n    }\n\n    public exit(data: WardenData): void {}\n\n    public update(data: WardenData, dt: number): WardenStateType | null {\n        data.timeInState += dt;\n        if (data.timeInState > 5.0) {\n            return \"HUNTING\";\n        }\n        return null;\n    }\n}\n",
  "src/gameplay/states/WardenHuntingState.ts": "import { WardenData } from \"../components/WardenData\";\nimport { IWardenState, WardenStateType } from \"./IWardenState\";\n\nexport class WardenHuntingState implements IWardenState {\n    public readonly type: WardenStateType = \"HUNTING\";\n    public readonly name = \"HUNTING\";\n    public readonly hue = \"#ef4444\";\n\n    public enter(data: WardenData): void {\n        data.timeInState = 0;\n    }\n\n    public exit(data: WardenData): void {}\n\n    public update(data: WardenData, dt: number): WardenStateType | null {\n        data.timeInState += dt;\n        if (data.timeInState > 10.0) {\n            return \"DORMANT\";\n        }\n        return null;\n    }\n}\n",
  "src/gameplay/systems/PlayerInputSystem.ts": "import { ISystem } from \"../../contracts/ISystem\";\n\nexport class PlayerInputSystem implements ISystem {\n    private keysPressed: Set<string> = new Set();\n    public readonly inputBuffer = { x: 0, y: 0, jump: false, fire: false };\n\n    public init(): void {\n        window.addEventListener(\"keydown\", this.handleKeyDown);\n        window.addEventListener(\"keyup\", this.handleKeyUp);\n    }\n\n    public update(dt: number): void {\n        let x = 0;\n        let y = 0;\n        if (this.keysPressed.has(\"w\") || this.keysPressed.has(\"arrowup\")) y += 1;\n        if (this.keysPressed.has(\"s\") || this.keysPressed.has(\"arrowdown\")) y -= 1;\n        if (this.keysPressed.has(\"a\") || this.keysPressed.has(\"arrowleft\")) x -= 1;\n        if (this.keysPressed.has(\"d\") || this.keysPressed.has(\"arrowright\")) x += 1;\n        \n        this.inputBuffer.x = x;\n        this.inputBuffer.y = y;\n        this.inputBuffer.jump = this.keysPressed.has(\" \");\n    }\n\n    public dispose(): void {\n        window.removeEventListener(\"keydown\", this.handleKeyDown);\n        window.removeEventListener(\"keyup\", this.handleKeyUp);\n    }\n\n    private handleKeyDown = (e: KeyboardEvent): void => {\n        this.keysPressed.add(e.key.toLowerCase());\n    };\n\n    private handleKeyUp = (e: KeyboardEvent): void => {\n        this.keysPressed.delete(e.key.toLowerCase());\n    };\n}\n",
  "src/gameplay/systems/PlayerMovementSystem.ts": "import { ISystem } from \"../../contracts/ISystem\";\nimport { PlayerData } from \"../components/PlayerData\";\nimport { PlayerInputSystem } from \"./PlayerInputSystem\";\n\nexport class PlayerMovementSystem implements ISystem {\n    constructor(\n        private playerData: PlayerData,\n        private inputSystem: PlayerInputSystem\n    ) {}\n\n    public update(dt: number): void {\n        const input = this.inputSystem.inputBuffer;\n        const speed = this.playerData.moveSpeed;\n        \n        this.playerData.velocityX = input.x * speed;\n        this.playerData.velocityY = input.y * speed;\n    }\n}\n",
  "src/gameplay/systems/WardenBrainSystem.ts": "import { ISystem } from \"../../contracts/ISystem\";\nimport { WardenData } from \"../components/WardenData\";\nimport { IWardenState, WardenStateType } from \"../states/IWardenState\";\nimport { WardenDormantState } from \"../states/WardenDormantState\";\nimport { WardenHuntingState } from \"../states/WardenHuntingState\";\nimport { EventBroker } from \"../../core/events/EventBroker\";\nimport { GameEvent } from \"../../core/events/GameEvents\";\n\nexport class WardenBrainSystem implements ISystem {\n    private currentState: IWardenState;\n    private states: Map<WardenStateType, IWardenState> = new Map();\n\n    constructor(\n        private wardenData: WardenData,\n        private broker: EventBroker\n    ) {\n        this.states.set(\"DORMANT\", new WardenDormantState());\n        this.states.set(\"HUNTING\", new WardenHuntingState());\n        this.currentState = this.states.get(\"DORMANT\") as IWardenState;\n    }\n\n    public init(): void {\n        this.currentState.enter(this.wardenData);\n        this.broker.publish(GameEvent.WARDEN_STATE_CHANGE, { \n            state: this.currentState.name, \n            hue: this.currentState.hue \n        });\n    }\n\n    public update(dt: number): void {\n        const nextStateType = this.currentState.update(this.wardenData, dt);\n        \n        if (nextStateType && nextStateType !== this.currentState.type) {\n            this.currentState.exit(this.wardenData);\n            \n            const nextState = this.states.get(nextStateType);\n            if (!nextState) throw new Error(`Warden state not found: ${nextStateType}`);\n            \n            this.currentState = nextState;\n            this.currentState.enter(this.wardenData);\n            \n            this.broker.publish(GameEvent.WARDEN_STATE_CHANGE, { \n                state: this.currentState.name, \n                hue: this.currentState.hue \n            });\n        }\n    }\n}\n",
  "src/gameplay/warden/WardenConfig.ts": "export const WardenConfig = {\n  phase2Threshold: 0.6,\n  attackChargeSpeed: 800,\n};\n",
  "src/index.css": ":root {\n  --void-bg: #050505;\n  --surface-bg: #0c0e12;\n  --signal-green: #22c55e;\n}\n\nhtml, body, #root {\n  margin: 0;\n  padding: 0;\n  width: 100vw;\n  height: 100vh;\n  background-color: var(--void-bg);\n  overflow: hidden;\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n}\n",
